#include "engine.h"
#include <cassert>
#include <iostream>
int main(){bench::Engine engine;engine.unload();engine.unload();try{engine.run(bench::Request());return 1;}catch(const std::runtime_error &e){assert(std::string(e.what())=="MODEL_NOT_LOADED");}engine.cancelled.store(true);try{engine.load("missing.gguf");return 2;}catch(const std::runtime_error &e){assert(std::string(e.what())=="CANCELLED");}engine.cancelled.store(false);try{engine.load("/definitely-missing-synthetic-model.gguf");return 3;}catch(const std::runtime_error &e){assert(std::string(e.what()).find("MODEL_LOAD_FAILED")==0);}bench::Engine second;try{second.load("/another-missing-synthetic-model.gguf");return 4;}catch(const std::runtime_error &e){assert(std::string(e.what()).find("MODEL_LOAD_FAILED")==0);}assert(bench::quote("\"\n") == "\"\\\"\\u000a\"");std::cout<<"PASS: real native core links and executes on host; absent model, cancelled load, failure recovery, idempotent unload and JSON escaping. No inference or device performance measured.\n";}
